const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // The question mentions the Norwegian Sea, but the coordinates are off the coast of Newfoundland, Canada.
    // The coordinates will be treated as the ground truth for the analysis.
    const point1 = ee.Geometry.Point([-50.925784, 46.694935]); // "Milky" point candidate
    const point2 = ee.Geometry.Point([-58.528990, 46.809436]); // Reference point
    const dateStart = '2019-09-19';
    const dateEnd = '2019-09-20';

    // 2. Data Acquisition & Cloud Masking
    // "Milky" water color is best observed using true-color reflectance.
    // We use a simple brightness metric (average of RGB) to quantify this.
    // Sentinel-2 is a good choice for this task.
    function maskS2CloudsAndWater(image) {
        const scl = image.select('SCL');
        // Keep only water pixels (SCL class 6)
        const waterMask = scl.eq(6);
        return image.updateMask(waterMask);
    }

    const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterDate(dateStart, dateEnd)
        .filterBounds(point1.union(point2));

    // 3. Initial Data Check
    const collectionSize = s2Collection.size().getInfo();
    if (collectionSize === 0) {
        console.log("No Sentinel-2 images found for the specified date and locations.");
        console.log("A: No");
        return;
    }

    const image = s2Collection.map(maskS2CloudsAndWater).mosaic();

    // Define bands for brightness calculation (True Color)
    const bands = ['B4', 'B3', 'B2'];
    const brightness = image.select(bands).reduce(ee.Reducer.mean()).rename('brightness');

    // 4. Processing and Calculation
    const scale = 30; // Scale for reduceRegion

    // Analyze Point 1
    const data1 = brightness.reduceRegion({
        reducer: ee.Reducer.first(),
        geometry: point1,
        scale: scale,
    });

    // Analyze Point 2
    const data2 = brightness.reduceRegion({
        reducer: ee.Reducer.first(),
        geometry: point2,
        scale: scale,
    });

    const brightness1 = data1.get('brightness').getInfo();
    const brightness2 = data2.get('brightness').getInfo();

    // 5. Validation & Final Answer
    if (brightness1 === null || brightness2 === null) {
        console.log("Data could not be extracted for one or both points.");
        console.log(`Point 1 (milky?) brightness: ${brightness1}`);
        console.log(`Point 2 (reference) brightness: ${brightness2}`);
        console.log("This could be due to cloud cover, lack of water, or sensor artifacts after masking.");
        console.log("B: No");
        return;
    }

    console.log(`Point 1 (milky?) avg. RGB reflectance: ${brightness1.toFixed(2)}`);
    console.log(`Point 2 (reference) avg. RGB reflectance: ${brightness2.toFixed(2)}`);

    if (brightness1 > brightness2) {
        console.log("Conclusion: Water at Point 1 is brighter (more 'milky') than at Point 2.");
        console.log("A: Yes");
    } else {
        console.log("Conclusion: Water at Point 1 is not brighter (less 'milky') than at Point 2.");
        console.log("B: No");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred during the analysis:", err);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
